module iir_filter(
    input clk,
    input rst,
    input signed [15:0] x, // Input sample
    output reg signed [15:0] y // Output sample
);
    parameter signed [15:0] b0 = 16'h0A00; // Coefficient for x[n]
    parameter signed [15:0] b1 = 16'h0500; // Coefficient for x[n-1]
    parameter signed [15:0] b2 = 16'h0200; // Coefficient for x[n-2]
    parameter signed [15:0] a1 = 16'hFF00; // Coefficient for y[n-1]
    parameter signed [15:0] a2 = 16'hFE00; // Coefficient for y[n-2]

    reg signed [15:0] x_1, x_2; // Delayed input samples
    reg signed [15:0] y_1, y_2; // Delayed output samples

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x_1 <= 0;
            x_2 <= 0;
            y_1 <= 0;
            y_2 <= 0;
            y <= 0;
        end else begin
            y <= (b0 * x + b1 * x_1 + b2 * x_2 - a1 * y_1 - a2 * y_2) >>> 12; // Fixed-point division
            x_2 <= x_1;
            x_1 <= x;
            y_2 <= y_1;
            y_1 <= y;
        end
    end
endmodule

