module kalman_filter (
    input wire clk,
    input wire rst,
    input wire [15:0] sensor1_meas,
    input wire [15:0] sensor2_meas,
    output reg [15:0] estimated_position,
    output reg [15:0] estimated_velocity
);

reg [15:0] position;
reg [15:0] velocity;
reg [15:0] p; // estimation error covariance
reg [15:0] q; // process noise covariance
reg [15:0] r; // measurement noise covariance
reg [15:0] k; // kalman gain

initial begin
    position = 0;
    velocity = 0;
    p = 1; // initial estimation error covariance
    q = 1; // process noise covariance
    r = 1; // measurement noise covariance
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        position <= 0;
        velocity <= 0;
        p <= 1;
    end else begin
        // Prediction step
        position <= position + velocity;
        p <= p + q;

        // Update step
        k <= p / (p + r); // Kalman Gain
        position <= position + k * (sensor1_meas + sensor2_meas)/2 - position; // update position
        velocity <= velocity; // velocity remains the same in this simple model
        p <= (1 - k) * p; // update estimation error covariance
    end
    estimated_position <= position;
    estimated_velocity <= velocity;
end

endmodule

module ethernet_mac_controller(  
    input clk,  
    input reset,  
    input start_tx,  
    input start_rx,  
    output reg [1:0] state  
);  
    // State encoding  
    parameter IDLE = 2'b00, TRANSMIT = 2'b01, RECEIVE = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start_tx)  
                        state <= TRANSMIT;  
                    else if (start_rx)  
                        state <= RECEIVE;  
                end  
                TRANSMIT: begin  
                    if (!start_tx)  
                        state <= IDLE;  
                end  
                RECEIVE: begin  
                    if (!start_rx)  
                        state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

