module sram_cell (  
    input wire [2:0] address,  
    input wire [7:0] data_in,  
    input wire we,  
    input wire re,  
    output reg [7:0] data_out,  
    output reg valid  
);  
    reg [7:0] memory [0:7];  // 8-bit SRAM with 8 locations  

    always @(posedge we or posedge re) begin  
        if (we) begin  
            memory[address] <= data_in;  
            valid <= 1'b0;  
        end  
        if (re) begin  
            data_out <= memory[address];  
            valid <= 1'b1;  
        end  
    end  
endmodule

