module virtual_memory_manager #(parameter PAGE_SIZE = 4, TABLE_SIZE = 16) (  
    input wire clk,  
    input wire rst,  
    input wire [31:0] virtual_address,  
    output reg [31:0] physical_address  
);  
    reg [31:0] page_table [0:TABLE_SIZE-1];  
    reg [31:0] page_offset;  
    reg [3:0] virtual_page;  
    reg [3:0] physical_frame;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            // Initialize page table with some values for testing  
            page_table[0] = 32'h00000000;  
            page_table[1] = 32'h00000004;  
            page_table[2] = 32'h00000008;  
            page_table[3] = 32'h0000000C;  
            page_table[4] = 32'h00000010;  
            page_table[5] = 32'h00000014;  
            page_table[6] = 32'h00000018;  
            page_table[7] = 32'h0000001C;  
            page_table[8] = 32'h00000020;  
            page_table[9] = 32'h00000024;  
            page_table[10] = 32'h00000028;  
            page_table[11] = 32'h0000002C;  
            page_table[12] = 32'h00000030;  
            page_table[13] = 32'h00000034;  
            page_table[14] = 32'h00000038;  
            page_table[15] = 32'h0000003C;  
        end else begin  
            virtual_page = virtual_address[31:PAGE_SIZE];  
            page_offset = virtual_address[PAGE_SIZE-1:0];  
