module viterbi_decoder (  
    input clk,  
    input reset,  
    input [1:0] input_bits,  
    output reg [1:0] decoded_bits,  
    output reg valid  
);  
    // State registers  
    reg [1:0] current_state, next_state;  
    reg [1:0] output_bits;  
    reg [3:0] path_metrics [0:3]; // Store path metrics for states  

    // State definitions  
    localparam S0 = 2'b00;  
    localparam S1 = 2'b01;  
    localparam S2 = 2'b10;  
    localparam S3 = 2'b11;  

    // Transition logic  
    always @(*) begin  
        case (current_state)  
            S0: begin  
                if (input_bits == 2'b00) begin  
                    next_state = S0;  
                    output_bits = 2'b00;  
                end else begin  
                    next_state = S1;  
                    output_bits = 2'b01;  
                end  
            end  
            S1: begin  
                if (input_bits == 2'b01) begin  
                    next_state = S2;  
                    output_bits = 2'b10;  
                end else begin  
                    next_state = S3;  
                    output_bits = 2'b11;  
                end  
            end  
            S2: begin  
                next_state = S0;  
                output_bits = 2'b00;  
            end  
            S3: begin  
                next_state = S1;  
                output_bits = 2'b01;  
            end  
            default: begin  
                next_state = S0;  
                output_bits = 2'b00;  
            end  
        endcase  
    end  

    // State update and output generation  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            current_state <= S0;  
            valid <= 0;  
        end else begin  
            current_state <= next_state;  
            decoded_bits <= output_bits;  
            valid <= 1;  
        end  
    end  
endmodule

