module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire activity,  
    output reg timer_out  
);  
    parameter TIMEOUT = 4; // timeout duration (in clock cycles)  
    reg [2:0] count; // 3-bit counter to count up to TIMEOUT  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            timer_out <= 1;  
        end else if (activity) begin  
            count <= 0;  
            timer_out <= 1;  
        end else if (count < TIMEOUT) begin  
            count <= count + 1;  
            timer_out <= 1;  
        end else begin  
            timer_out <= 0;  
        end  
    end  
endmodule

