module rc_oscillator(
    input wire clk,
    input wire reset,
    input wire [7:0] frequency,
    output reg output_signal
);
    reg [31:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            output_signal <= 0;
        end else begin
            if (counter >= frequency) begin
                output_signal <= ~output_signal;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

