module crc16_generator(  
    input wire clk,  
    input wire rst,  
    input wire [15:0] data_in,  
    input wire start,  
    output reg [15:0] crc_out,  
    output reg done  
);  
    reg [15:0] crc;  
    reg [15:0] polynomial;  
    reg [4:0] bit_count;  
    reg working;  

    initial begin  
        polynomial = 16'hA001;  
        crc = 16'h0000;  
        done = 0;  
        working = 0;  
    end  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            crc <= 16'h0000;  
            done <= 0;  
            working <= 0;  
            bit_count <= 0;  
        end else if (start && !working) begin  
            crc <= data_in;  
            bit_count <= 16;  
            working <= 1;  
            done <= 0;  
        end else if (working) begin  
            if (bit_count > 0) begin  
                if (crc[15])  
                    crc <= (crc << 1) ^ polynomial;  
                else  
                    crc <= crc << 1;  
                bit_count <= bit_count - 1;  
            end else begin  
                crc_out <= crc;  
                done <= 1;  
                working <= 0;  
            end  
        end  
    end  
endmodule

