module kalman_filter (  
    input wire clk,  
    input wire reset,  
    input wire [15:0] measurement,  
    output reg [15:0] estimated_position,  
    output reg [15:0] estimated_velocity  
);  
    // Kalman filter parameters  
    parameter [15:0] R = 16'h0001; // measurement noise  
    parameter [15:0] Q = 16'h0001; // process noise  
    parameter [15:0] K_gain = 16'h0001; // gain  
    reg [15:0] position_estimate;  
    reg [15:0] velocity_estimate;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            position_estimate <= 16'h0000;  
            velocity_estimate <= 16'h0000;  
            estimated_position <= 16'h0000;  
            estimated_velocity <= 16'h0000;  
        end else begin  
            // Prediction update  
            position_estimate <= position_estimate + velocity_estimate;  
            velocity_estimate <= velocity_estimate;  

            // Measurement update  
            estimated_position <= position_estimate + K_gain * (measurement - position_estimate);  
            estimated_velocity <= velocity_estimate + K_gain * (measurement - position_estimate);  
        end  
    end  
endmodule

