module pulse_generator(
    input wire clk,
    input wire start,
    input wire [3:0] duration,
    output reg pulse
);
    reg [3:0] count;
    reg active;

    always @(posedge clk) begin
        if (start) begin
            count <= duration;
            active <= 1'b1;
        end else if (active) begin
            if (count > 0) begin
                count <= count - 1;
            end else begin
                active <= 1'b0;
                pulse <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (active) begin
            pulse <= 1'b1;
        end else begin
            pulse <= 1'b0;
        end
    end
endmodule

