module simple_des(  
    input [63:0] plaintext,  
    input [55:0] key,  
    input clk,  
    input rst,  
    output reg [63:0] ciphertext  
);  

    reg [63:0] L, R;  
    reg [55:0] subkey;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            L <= 64'b0;  
            R <= 64'b0;  
            ciphertext <= 64'b0;  
        end else begin  
            // Initial permutation (simplified)  
            L <= plaintext[63:32];  
            R <= plaintext[31:0];  
            subkey <= key;  

            // Simple round function (not actual DES)
            R <= R ^ (subkey[55:0] & L);  
            L <= L ^ (subkey[55:0] & R);  

            // Combine L and R to form ciphertext  
            ciphertext <= {L, R};  
        end  
    end  
endmodule

