module rsa_encryptor(  
    input clk,  
    input rst,  
    input [63:0] plaintext,  
    input [63:0] n,  
    input [63:0] e,  
    output reg [63:0] ciphertext,  
    output reg done  
);  

    reg [63:0] result;  
    reg [63:0] temp;  
    reg [5:0] count;  
    reg calculating;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            ciphertext <= 0;  
            done <= 0;  
            result <= 1;  
            count <= 0;  
            calculating <= 0;  
        end else if (calculating) begin  
            if (count < e) begin  
                if (e[count]) begin  
                    result <= (result * temp) % n;  
                end  
                temp <= (temp * temp) % n;  
                count <= count + 1;  
            end else begin  
                ciphertext <= result;  
                done <= 1;  
                calculating <= 0;  
            end  
        end else begin  
            // Start calculation on the first clock after input  
            temp <= plaintext;  
            count <= 0;  
            calculating <= 1;  
        end  
    end  
endmodule

