module serializer_32bit(  
    input clk,  
    input reset,  
    input [31:0] data_in,  
    output reg serial_out  
);  
    reg [4:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            serial_out <= 0;  
        end else if (counter < 32) begin  
            serial_out <= data_in[counter];  
            counter <= counter + 1;  
        end  
    end  
endmodule

