module dma_controller(
    input wire clk,
    input wire reset,
    input wire start,
    input wire read_enable,
    input wire write_enable,
    input wire [7:0] data_in,
    input wire [7:0] address,
    output reg [7:0] data_out,
    output reg done
);
    reg [1:0] state;

    localparam IDLE = 2'b00,
               READ = 2'b01,
               WRITE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            data_out <= 8'b0;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        if (read_enable) begin
                            state <= READ;
                        end else if (write_enable) begin
                            state <= WRITE;
                        end
                        done <= 1'b0;
                    end
                end

                READ: begin
                    data_out <= data_in; // Simulate data read
                    state <= IDLE;
                    done <= 1'b1;
                end

                WRITE: begin
                    // Simulate writing data (data_in to memory at address)
                    state <= IDLE;
                    done <= 1'b1;
                end
            endcase
        end
    end
endmodule

