module interrupt_controller(  
    input clk,  
    input reset,  
    input [3:0] interrupt_requests,  
    output reg interrupt_out,  
    output reg [1:0] active_interrupt  
);  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            interrupt_out <= 0;  
            active_interrupt <= 2'b00;  
        end else begin  
            if (|interrupt_requests) begin  
                interrupt_out <= 1;  
                if (interrupt_requests[3]) begin  
                    active_interrupt <= 2'b11; // highest priority  
                end else if (interrupt_requests[2]) begin  
                    active_interrupt <= 2'b10;  
                end else if (interrupt_requests[1]) begin  
                    active_interrupt <= 2'b01;  
                end else if (interrupt_requests[0]) begin  
                    active_interrupt <= 2'b00;  
                end  
            end else begin  
                interrupt_out <= 0;  
                active_interrupt <= 2'b00;  
            end  
        end  
    end  
endmodule

