module fir_filter (
    input clk,
    input reset,
    input [3:0] x,
    output reg [3:0] y
);
    reg [3:0] coeff [0:3]; // Coefficients for FIR filter
    reg [7:0] sum;         // Sum for the output
    reg [3:0] delay [0:2]; // Delay elements

    initial begin
        coeff[0] = 4'b0001; // Coefficient 1
        coeff[1] = 4'b0010; // Coefficient 2
        coeff[2] = 4'b0011; // Coefficient 3
        coeff[3] = 4'b0100; // Coefficient 4
        delay[0] = 4'b0000; // Initial delay values
        delay[1] = 4'b0000;
        delay[2] = 4'b0000;
        sum = 8'b00000000;   // Initial sum
        y = 4'b0000;         // Initial output
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            delay[0] <= 4'b0000;
            delay[1] <= 4'b0000;
            delay[2] <= 4'b0000;
            y <= 4'b0000;
            sum <= 8'b00000000;
        end else begin
            // Shift delay registers
            delay[2] <= delay[1];
            delay[1] <= delay[0];
            delay[0] <= x;

            // Calculate the output sum
            sum <= (coeff[0] * delay[0]) + (coeff[1] * delay[1]) + (coeff[2] * delay[2]) + 
                    (coeff[3] * delay[2]); // Note: delay[2] is used twice for simplicity

            // Assign the output
            y <= sum[3:0]; // Use only the lower 4 bits for output
        end
    end
endmodule

module vector_adder(
