module convolutional_encoder (
    input wire clk,
    input wire reset,
    input wire data_in,
    output reg [1:0] data_out
);
    reg [2:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3'b000;
            data_out <= 2'b00;
        end else begin
            state <= {state[1:0], data_in}; // Shift in the new data
            // Calculate the output based on the state
            data_out[0] <= state[2] ^ state[1] ^ state[0]; // First polynomial (111)
            data_out[1] <= state[2] ^ state[0];           // Second polynomial (101)
        end
    end
endmodule

module zero_cross_detector(  
    input wire clk,  
    input wire signal_in,  
    output reg zero_cross  
);  
    reg previous_signal;  

    always @(posedge clk) begin  
        if ((previous_signal == 1'b0 && signal_in == 1'b1) || (previous_signal == 1'b1 && signal_in == 1'b0)) begin  
            zero_cross <= 1'b1;  
        end else begin  
            zero_cross <= 1'b0;  
        end  
        previous_signal <= signal_in;  
    end  
endmodule

module stack (
    input clk,
    input reset,
    input push,
    input pop,
    input [7:0] data_in,
    output reg [7:0] data_out,
    output reg empty,
    output reg full
);
    reg [7:0] stack_mem [0:7];
    reg [2:0] top;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            top <= 3'b000;
            empty <= 1;
            full <= 0;
        end else begin
            if (push && !full) begin
                stack_mem[top] <= data_in;
                top <= top + 1;
                empty <= 0;
                if (top + 1 == 8) full <= 1;
            end
            if (pop && !empty) begin
                top <= top - 1;
                data_out <= stack_mem[top];
                if (top == 1) empty <= 1;
                full <= 0;
            end
        end
    end
endmodule

module histogram_equalization (
    input [255:0] histogram_in,
    output reg [255:0] histogram_out
);
    integer i;
    integer sum;
    reg [15:0] CDF [0:255]; // Cumulative Distribution Function
    reg [15:0] total_pixels;

    always @(*) begin
        // Initialize CDF
        total_pixels = 0;
        for (i = 0; i < 256; i = i + 1) begin
            total_pixels = total_pixels + histogram_in[i];
            CDF[i] = total_pixels;
        end

        // Calculate equalized histogram
        for (i = 0; i < 256; i = i + 1) begin
            histogram_out[i] = (CDF[i] * 255) / total_pixels;
        end
    end
endmodule

module fractional_n_pll(
    input wire clk_ref,
    input wire reset,
    input wire [7:0] frac_div_ratio, // Fractional division ratio
    output reg clk_out
);
    reg [15:0] counter; // Counter for frequency division
    reg [15:0] div_int; // Integer part of the division ratio
    reg [15:0] div_frac; // Fractional part of the division ratio
    reg [15:0] frac_counter; // Counter for fractional division

    // Split the fractional division ratio into integer and fractional parts
    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            div_int <= 0;
            div_frac <= 0;
            counter <= 0;
            frac_counter <= 0;
            clk_out <= 0;
        end else begin
            div_int <= frac_div_ratio[7:4]; // Example split, 4 MSBs as integer
            div_frac <= frac_div_ratio[3:0]; // 4 LSBs as fractional

            // Increment the integer counter
            if (counter < div_int) begin
                counter <= counter + 1;
            end else begin
                counter <= 0;
                clk_out <= ~clk_out; // Toggle output clock
                // Handle fractional division
                if (frac_counter < div_frac) begin
                    frac_counter <= frac_counter + 1;
                end else begin
                    frac_counter <= 0;
                    clk_out <= ~clk_out; // Additional toggle for fractional part
                end
            end
        end
    end
endmodule

module interrupt_controller (
    input clk,
    input rst,
    input [3:0] irq,      // 4 interrupt requests
    input ack,           // Acknowledge signal
    output reg irq_out,   // Current interrupt output
    output reg [1:0] irq_served // Indicates which interrupt is being serviced
);

    reg [3:0] irq_pending;
    reg [1:0] current_irq;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            irq_pending <= 4'b0000;
            current_irq <= 2'b00;
            irq_out <= 0;
        end else begin
            // Capture pending IRQs
            irq_pending <= irq_pending | irq;

            // Service the highest priority IRQ
            if (irq_pending != 4'b0000) begin
                irq_out <= 1;
                current_irq <= current_irq + 1; // Move to next interrupt
                irq_pending <= irq_pending & ~(1 << current_irq); // Clear serviced IRQ
                irq_served <= current_irq;
            end else begin
                irq_out <= 0; // No interrupt to service
            end
        end
    end
endmodule

